   307→    // check the actual storage of the contract - it should be:
   308→    // * The storage value at header.timestamp % HISTORY_BUFFER_LENGTH should be
   309→    // header.timestamp
   310→    // * The storage value at header.timestamp % HISTORY_BUFFER_LENGTH + HISTORY_BUFFER_LENGTH //
